/**
 * Media API for uploading, downloading, and managing media files.
 *
 * This module provides methods for interacting with the Matrix Content Repository API.
 * @see https://spec.matrix.org/v1.11/client-server-api/#matrix-content-repository
 */

import { type ContentType } from "./@types/content.ts";

/**
 * Response from a successful media upload.
 */
export interface MediaUploadResponse {
    /**
     * The MXC URI for the uploaded content.
     */
    content_uri: string;
}

/**
 * Parameters for uploading media.
 */
export interface MediaUploadOptions {
    /**
     * The content type of the file being uploaded.
     * Defaults to application/octet-stream if not specified.
     */
    contentType?: ContentType;
    /**
     * The filename to set for the upload.
     */
    filename?: string;
}

/**
 * Media configuration response from the homeserver.
 */
export interface MediaConfigResponse {
    /**
     * The maximum size of an upload in bytes.
     */
    "m.upload.size"?: number;
}

/**
 * Media API class for handling media operations.
 */
export class MediaApi {
    /**
     * Creates a new MediaApi instance.
     *
     * @param baseUrl - The base URL of the homeserver.
     * @param accessToken - The access token for authenticated requests.
     */
    public constructor(
        private readonly baseUrl: string,
        private readonly accessToken?: string,
    ) {}

    /**
     * Upload media to the content repository.
     *
     * @param file - The file data as a Buffer, Blob, or string.
     * @param options - Optional upload parameters.
     * @returns Promise resolving to the content URI of the uploaded file.
     * @see https://spec.matrix.org/v1.11/client-server-api/#post_matrixmediav3upload
     */
    public async upload(file: Buffer | Blob | string, options?: MediaUploadOptions): Promise<MediaUploadResponse> {
        const formData = new FormData();
        const blob = file instanceof Blob ? file : new Blob([file]);

        formData.append("file", blob, options?.filename || "upload");

        const url = new URL("/_matrix/media/v3/upload", this.baseUrl);
        if (options?.filename) {
            url.searchParams.set("filename", options.filename);
        }

        const headers: Record<string, string> = {};
        if (options?.contentType) {
            headers["Content-Type"] = options.contentType;
        }
        if (this.accessToken) {
            headers["Authorization"] = `Bearer ${this.accessToken}`;
        }

        const response = await fetch(url.href, {
            method: "POST",
            headers,
            body: formData,
        });

        if (!response.ok) {
            const error = await response.text();
            throw new Error(`Failed to upload media: ${response.status} ${response.statusText} - ${error}`);
        }

        return response.json() as Promise<MediaUploadResponse>;
    }

    /**
     * Download media from the content repository.
     *
     * @param serverName - The homeserver name (e.g., "matrix.org").
     * @param mediaId - The media ID.
     * @param allowRedirects - Whether to allow redirects. Defaults to true.
     * @returns Promise resolving to the media data as a Blob.
     * @see https://spec.matrix.org/v1.11/client-server-api/#get_matrixmediav3downloadservernamemediaid
     */
    public async download(serverName: string, mediaId: string, allowRedirects = true): Promise<Blob> {
        const url = new URL(`/_matrix/media/v3/download/${encodeURIComponent(serverName)}/${encodeURIComponent(mediaId)}`, this.baseUrl);

        if (allowRedirects !== undefined) {
            url.searchParams.set("allow_redirect", String(allowRedirects));
        }

        const headers: Record<string, string> = {};
        if (this.accessToken) {
            headers["Authorization"] = `Bearer ${this.accessToken}`;
        }

        const response = await fetch(url.href, {
            method: "GET",
            headers,
        });

        if (!response.ok) {
            throw new Error(`Failed to download media: ${response.status} ${response.statusText}`);
        }

        return response.blob();
    }

    /**
     * Download media as an ArrayBuffer.
     *
     * @param serverName - The homeserver name (e.g., "matrix.org").
     * @param mediaId - The media ID.
     * @param allowRedirects - Whether to allow redirects. Defaults to true.
     * @returns Promise resolving to the media data as an ArrayBuffer.
     */
    public async downloadAsArrayBuffer(serverName: string, mediaId: string, allowRedirects = true): Promise<ArrayBuffer> {
        const blob = await this.download(serverName, mediaId, allowRedirects);
        return blob.arrayBuffer();
    }

    /**
     * Download media as a data URL.
     *
     * @param serverName - The homeserver name (e.g., "matrix.org").
     * @param mediaId - The media ID.
     * @param allowRedirects - Whether to allow redirects. Defaults to true.
     * @returns Promise resolving to the media data as a base64 data URL.
     */
    public async downloadAsDataUrl(serverName: string, mediaId: string, allowRedirects = true): Promise<string> {
        const blob = await this.download(serverName, mediaId, allowRedirects);
        return new Promise<string>((resolve: (value: string) => void, reject: (reason: Error) => void) => {
            const reader = new FileReader();
            reader.onloadend = (): void => resolve(reader.result as string);
            reader.onerror = (): void => reject(new Error("Failed to convert blob to data URL"));
            reader.readAsDataURL(blob);
        });
    }

    /**
     * Get a thumbnail for media.
     *
     * @param serverName - The homeserver name (e.g., "matrix.org").
     * @param mediaId - The media ID.
     * @param width - The desired width of the thumbnail.
     * @param height - The desired height of the thumbnail.
     * @param method - The resize method ("crop" or "scale"). Defaults to "scale".
     * @param allowRedirects - Whether to allow redirects. Defaults to true.
     * @returns Promise resolving to the thumbnail data as a Blob.
     * @see https://spec.matrix.org/v1.11/client-server-api/#get_matrixmediav3thumbnailservernamemediaid
     */
    public async getThumbnail(
        serverName: string,
        mediaId: string,
        width: number,
        height: number,
        method: "crop" | "scale" = "scale",
        allowRedirects = true,
    ): Promise<Blob> {
        const url = new URL(`/_matrix/media/v3/thumbnail/${encodeURIComponent(serverName)}/${encodeURIComponent(mediaId)}`, this.baseUrl);

        url.searchParams.set("width", Math.round(width).toString());
        url.searchParams.set("height", Math.round(height).toString());
        url.searchParams.set("method", method);
        url.searchParams.set("allow_redirect", String(allowRedirects));

        const headers: Record<string, string> = {};
        if (this.accessToken) {
            headers["Authorization"] = `Bearer ${this.accessToken}`;
        }

        const response = await fetch(url.href, {
            method: "GET",
            headers,
        });

        if (!response.ok) {
            throw new Error(`Failed to get thumbnail: ${response.status} ${response.statusText}`);
        }

        return response.blob();
    }

    /**
     * Get a thumbnail as a data URL.
     *
     * @param serverName - The homeserver name (e.g., "matrix.org").
     * @param mediaId - The media ID.
     * @param width - The desired width of the thumbnail.
     * @param height - The desired height of the thumbnail.
     * @param method - The resize method ("crop" or "scale"). Defaults to "scale".
     * @param allowRedirects - Whether to allow redirects. Defaults to true.
     * @returns Promise resolving to the thumbnail data as a base64 data URL.
     */
    public async getThumbnailAsDataUrl(
        serverName: string,
        mediaId: string,
        width: number,
        height: number,
        method: "crop" | "scale" = "scale",
        allowRedirects = true,
    ): Promise<string> {
        const blob = await this.getThumbnail(serverName, mediaId, width, height, method, allowRedirects);
        return new Promise<string>((resolve: (value: string) => void, reject: (reason: Error) => void) => {
            const reader = new FileReader();
            reader.onloadend = (): void => resolve(reader.result as string);
            reader.onerror = (): void => reject(new Error("Failed to convert blob to data URL"));
            reader.readAsDataURL(blob);
        });
    }

    /**
     * Get the media configuration from the homeserver.
     *
     * @returns Promise resolving to the media configuration.
     * @see https://spec.matrix.org/v1.11/client-server-api/#get_matrixmediav1config
     */
    public async getConfig(): Promise<MediaConfigResponse> {
        const url = new URL("/_matrix/media/v1/config", this.baseUrl);

        const headers: Record<string, string> = {};
        if (this.accessToken) {
            headers["Authorization"] = `Bearer ${this.accessToken}`;
        }

        const response = await fetch(url.href, {
            method: "GET",
            headers,
        });

        if (!response.ok) {
            throw new Error(`Failed to get media config: ${response.status} ${response.statusText}`);
        }

        return response.json() as Promise<MediaConfigResponse>;
    }

    /**
     * Get the maximum upload size configured on the homeserver.
     *
     * @returns Promise resolving to the maximum upload size in bytes, or null if not configured.
     */
    public async getMaxUploadSize(): Promise<number | null> {
        const config = await this.getConfig();
        return config["m.upload.size"] ?? null;
    }
}
